"use client";

import * as React from "react";
import { useMemo } from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { Button } from "./button";
import { Label } from "./label";
import { Separator } from "./separator";
import { Tooltip } from "./tooltip";

import { useDescendantFlags } from "../lib/descendant-flags";
import { FieldControlContext } from "../lib/field-context";
import { cn } from "../lib/utils";
import { Icon } from "./icon";

import helperStyles from "./helpers.module.css";

const setFlags = {
  "data-has-choice-group": ':scope > :is([data-slot="checkbox-group"], [data-slot="radio-group"])'
};
const childrenOnly = { subtree: false };
const fieldFlags = {
  "data-has-content": ':scope > [data-slot="field-content"]',
  "data-has-disabled": ":disabled"
};
const fieldWatch = { attributes: ["disabled"] };
const labelFlags = {
  "data-has-checked": '[data-state="checked"]',
  "data-has-field": ':scope > [data-slot="field"]',
  "data-has-disabled": ":disabled, [data-disabled]",
  "data-has-focus-visible": ":focus-visible"
};
const labelWatch = { attributes: ["data-state", "disabled", "data-disabled"], focus: true };

function FieldSet({ className, ref, ...props }: React.ComponentProps<"fieldset">) {
  const setRef = useDescendantFlags(setFlags, childrenOnly, ref);
  return (
    <fieldset
      ref={setRef}
      data-slot="field-set"
      className={cn("flex flex-col gap-4 data-[has-choice-group]:gap-3", className)}
      {...props}
    />
  );
}
FieldSet.displayName = "FieldSet";

function FieldLegend({
  className,
  variant = "legend",
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"legend"> & { variant?: "legend" | "label" } & {
  ref?: React.Ref<React.ComponentRef<"legend">>;
}) {
  return (
    <legend
      ref={ref}
      data-slot="field-legend"
      data-variant={variant}
      className={cn(helperStyles.fieldLegend, className)}
      {...props}
    />
  );
}
FieldLegend.displayName = "FieldLegend";

function FieldGroup({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="field-group"
      className={cn(
        helperStyles.fieldGroup,
        "group/field-group @container/field-group flex w-full flex-col data-[slot=checkbox-group]:gap-3 *:data-[slot=field-group]:gap-4",
        className
      )}
      {...props}
    />
  );
}
FieldGroup.displayName = "FieldGroup";

const fieldVariants = cva("group/field flex w-full", {
  variants: {
    orientation: {
      vertical: "flex-col *:w-full [&>.sr-only]:w-auto",
      horizontal:
        "flex-row items-center data-[has-content]:items-start *:data-[slot=field-label]:flex-auto data-[has-content]:[&>[role=checkbox],[role=radio]]:mt-px",
      responsive:
        "flex-col *:w-full @md/field-group:flex-row @md/field-group:items-center @md/field-group:*:w-auto @md/field-group:data-[has-content]:items-start @md/field-group:*:data-[slot=field-label]:flex-auto [&>.sr-only]:w-auto @md/field-group:data-[has-content]:[&>[role=checkbox],[role=radio]]:mt-px"
    }
  },
  defaultVariants: {
    orientation: "vertical"
  }
});

function Field({
  className,
  orientation = "vertical",
  label,
  description,
  error,
  optional = false,
  help,
  group = false,
  wide = false,
  children,
  id,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> &
  VariantProps<typeof fieldVariants> & {
    label?: React.ReactNode;
    description?: React.ReactNode;
    error?: string;
    optional?: boolean;
    wide?: boolean;
  } & (
    | {
        /** Help beside the label, outside its accessible name: a string becomes a FieldHelp tooltip, a node (FieldHelp with its own label, GlobPatternHelp) renders as given. A group field takes none, because its legend names the group. */
        help?: React.ReactNode;
        group?: false;
      }
    | { help?: never; group: true }
  ) & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  const generated = React.useId();
  const child = React.isValidElement<{ id?: string }>(children) ? children : null;
  const controlId = child?.props.id ?? id ?? generated;
  const noteId = `${controlId}-note`;
  const fieldRef = useDescendantFlags(fieldFlags, fieldWatch, ref);
  const labelId = `${controlId}-label`;
  const hasNote =
    Boolean(error) || (description != null && description !== false && description !== "");
  const attributes = {
    id: group ? undefined : controlId,
    "aria-describedby": hasNote ? noteId : undefined,
    "aria-invalid": Boolean(error) || undefined,
    "aria-labelledby": group ? undefined : labelId
  };
  const control =
    child && typeof child.type === "string"
      ? React.cloneElement(child, { ...attributes })
      : children;
  const note = hasNote && (
    <p
      id={noteId}
      role={error ? "alert" : undefined}
      className={error ? helperStyles.fieldError : helperStyles.fieldDescription}
    >
      {error && <Icon name="alert" size={14} />}
      {error ? <span>{error}</span> : description}
    </p>
  );
  return (
    <FieldControlContext value={label ? attributes : {}}>
      <div
        ref={fieldRef}
        role={label ? undefined : "group"}
        data-slot="field"
        data-orientation={orientation}
        data-width={wide ? "wide" : undefined}
        data-invalid={Boolean(error) || undefined}
        className={cn(fieldVariants({ orientation }), helperStyles.field, className)}
        {...props}
      >
        {label ? (
          group ? (
            <fieldset className={helperStyles.fieldset}>
              <legend id={labelId}>
                {label}
                {optional && " (optional)"}
              </legend>
              <div className={helperStyles.fieldControl}>{control}</div>
              {note}
            </fieldset>
          ) : (
            <>
              <div className={helperStyles.fieldLabels}>
                <div className={helperStyles.fieldLabelRow}>
                  <FieldLabel id={labelId} htmlFor={controlId}>
                    {label}
                    {optional && " (optional)"}
                  </FieldLabel>
                  {typeof help === "string" ? <FieldHelp>{help}</FieldHelp> : help}
                </div>
              </div>
              <div className={helperStyles.fieldControl}>
                {control}
                {note}
              </div>
            </>
          )
        ) : (
          children
        )}
      </div>
    </FieldControlContext>
  );
}
Field.displayName = "Field";

function FieldContent({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="field-content"
      className={cn("group/field-content flex flex-1 flex-col gap-1", className)}
      {...props}
    />
  );
}
FieldContent.displayName = "FieldContent";

function FieldLabel({ className, ref, ...props }: React.ComponentProps<typeof Label>) {
  const labelRef = useDescendantFlags(labelFlags, labelWatch, ref);
  return (
    <Label
      ref={labelRef}
      data-slot="field-label"
      className={cn(
        "group/field-label peer/field-label flex w-fit gap-2 border-[color:var(--v4-line-soft)] group-data-[disabled=true]/field:opacity-50 data-[has-checked]:border-[color:var(--v4-choice-selected-border)] data-[has-checked]:bg-[color:var(--v4-choice-selected-surface)] data-[has-field]:rounded-lg data-[has-field]:border data-[has-field]:not-data-[has-disabled]:hover:bg-[color:var(--v4-hover)] data-[has-field]:data-[has-focus-visible]:border-ring data-[has-field]:data-[has-focus-visible]:ring-2 data-[has-field]:data-[has-focus-visible]:ring-[color:var(--v4-focus-ring)] *:data-[slot=field]:p-2.5",
        "data-[has-field]:w-full data-[has-field]:flex-col",
        className
      )}
      {...props}
    />
  );
}
FieldLabel.displayName = "FieldLabel";

function FieldHelp({
  label = "More information",
  children
}: {
  /** The info button's accessible name; keep it short and say what the help is about. */
  label?: string;
  children: React.ReactNode;
}) {
  return (
    <Tooltip content={children}>
      <Button
        type="button"
        variant="ghost"
        size="icon-xs"
        aria-label={label}
        data-slot="field-help"
        className={helperStyles.fieldHelp}
      >
        <Icon name="info" />
      </Button>
    </Tooltip>
  );
}
FieldHelp.displayName = "FieldHelp";

function FieldTitle({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="field-label"
      className={cn(
        helperStyles.fieldTitle,
        "flex w-fit items-center gap-2 group-data-[disabled=true]/field:opacity-50",
        className
      )}
      {...props}
    />
  );
}
FieldTitle.displayName = "FieldTitle";

function FieldDescription({ className, ref, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      ref={ref}
      data-slot="field-description"
      className={cn(
        helperStyles.fieldDescription,
        "text-muted-foreground text-left group-data-[orientation=horizontal]/field:text-balance [[data-variant=legend]+&]:-mt-1.5",
        "last:mt-0 nth-last-2:-mt-1",
        className
      )}
      {...props}
    />
  );
}
FieldDescription.displayName = "FieldDescription";

function FieldSeparator({
  children,
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & {
  children?: React.ReactNode;
} & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  return (
    <div
      ref={ref}
      data-slot="field-separator"
      data-content={!!children}
      className={cn(
        "relative -my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2",
        className
      )}
      {...props}
    >
      <Separator className="absolute inset-0 top-1/2" />
      {children && (
        <span
          className="text-muted-foreground relative mx-auto block w-fit bg-background px-2"
          data-slot="field-separator-content"
        >
          {children}
        </span>
      )}
    </div>
  );
}
FieldSeparator.displayName = "FieldSeparator";

function FieldError({
  className,
  children,
  errors,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & {
  errors?: Array<{ message?: string } | undefined>;
} & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  const content = useMemo(() => {
    if (children) {
      return children;
    }

    const messages = [
      ...new Set((errors ?? []).map((error) => error?.message).filter(Boolean))
    ] as string[];
    if (messages.length < 2) return messages[0] ?? null;
    return (
      <span className={helperStyles.fieldErrorLines}>
        {messages.map((message) => (
          <span key={message}>{message}</span>
        ))}
      </span>
    );
  }, [children, errors]);

  if (!content) {
    return null;
  }

  return (
    <div
      ref={ref}
      role="alert"
      data-slot="field-error"
      className={cn(helperStyles.fieldError, className)}
      {...props}
    >
      <Icon name="alert" size={14} />
      <span>{content}</span>
    </div>
  );
}
FieldError.displayName = "FieldError";

export {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldHelp,
  FieldLabel,
  FieldLegend,
  FieldSeparator,
  FieldSet,
  FieldTitle
};

.avatarFallback {
  background: var(--v4-tint);
  color: var(--v4-ink);
  font-family: var(--v4-type-label-font-family);
  font-weight: var(--v4-type-label-font-weight);
  line-height: 1;
  letter-spacing: 0;
}
.avatarFallback svg {
  width: 50%;
  height: 50%;
  max-width: var(--v4-size-icon);
  max-height: var(--v4-size-icon);
}
.count {
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
  display: inline-flex;
  min-width: var(--v4-size-count);
  height: var(--v4-size-count);
  padding: 0 var(--v4-space-4);
  align-items: center;
  justify-content: center;
  border-radius: 0;
  background: var(--v4-accent);
  color: var(--v4-on-accent);
}
.countInk {
  background: var(--v4-ink);
  color: var(--v4-surface);
}
.countNeutral {
  background: var(--v4-tint);
  color: var(--v4-text2);
}
.identity {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.identityText {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.identityTitle {
  font-family: var(--v4-type-row-title-font-family);
  font-size: var(--v4-type-row-title-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-row-title-font-weight);
  letter-spacing: var(--v4-type-row-title-letter-spacing);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.identityDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-text2, var(--muted-foreground));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mono {
  font-family: var(--v4-font-mono, monospace);
}
.media {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  color: var(--v4-ink, var(--foreground));
  background: var(--v4-surface);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
  border-radius: 0;
}
.mediaSmall {
  width: 24px;
  height: 24px;
}
.tile {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: var(--v4-space-12);
  text-align: start;
  border: 1px solid var(--v4-line-soft, var(--border));
  background: var(--v4-surface, var(--background));
  color: var(--v4-ink, var(--foreground));
}
.tile:hover {
  border-color: var(--v4-control, var(--border));
  background: var(--v4-hover);
}
.tile[data-in-frame] {
  border-color: transparent;
  background: var(--v4-tint);
}
.tile[data-in-frame]:hover {
  background: color-mix(in srgb, var(--v4-mix-ink) var(--v4-hover-mix), var(--v4-tint));
}
.tile[aria-pressed="true"] {
  border-color: var(--v4-ink, var(--foreground));
}
.tile:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.tile:focus-visible {
  outline: 2px solid var(--ring, var(--ring));
  outline-offset: 2px;
}
.tileBody {
  flex: 1;
  min-width: 0;
}
.banner {
  display: flex;
  width: 100%;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  border: 1px solid var(--v4-accent-line);
  background: var(--v4-accent-wash);
  color: var(--v4-ink, var(--foreground));
  padding: 10px 16px;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.banner > svg {
  flex: 0 0 auto;
  color: var(--v4-accent-fg);
}
.bannerText {
  flex: 1;
  min-width: min(100%, 160px);
}
.steps {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 0;
  margin: 0;
  list-style: none;
}
.step {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
  color: var(--v4-muted, var(--muted-foreground));
}
.step[data-current] {
  color: var(--v4-ink, var(--foreground));
  font-weight: var(--v4-type-title-sm-font-weight);
}
.stepNumber {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: 1px solid var(--v4-line-soft, var(--border));
}
.step[data-current] .stepNumber {
  background: repeating-linear-gradient(
    135deg,
    var(--v4-tint, var(--muted)) 0 2px,
    transparent 2px 4px
  );
  border-color: var(--v4-ink, var(--foreground));
}
:global(.v4) {
  --v4-toast-bottom: calc(var(--v4-size-action-bar) + 2 * var(--v4-space-action-bar-offset));
}
:global(.v4)[data-action-bar-reserve] {
  --v4-toast-bottom: calc(2 * var(--v4-size-action-bar) + 3 * var(--v4-space-action-bar-offset));
}
.toastFixed {
  position: fixed;
  inset-inline-end: var(--v4-space-16);
  bottom: var(--v4-toast-bottom);
  z-index: 100;
  transition: bottom var(--v4-duration-moderate) var(--v4-ease-standard);
}
@media (prefers-reduced-motion: reduce) {
  .toastFixed {
    transition-duration: 0s;
  }
}
.toastTitle {
  font-family: var(--v4-type-row-title-font-family);
  font-size: var(--v4-type-row-title-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-row-title-font-weight);
  letter-spacing: var(--v4-type-row-title-letter-spacing);
}
.toastDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  margin-top: 2px;
  color: var(--v4-text2, var(--muted-foreground));
}
.avatarStatus[data-status="ok"] {
  background: var(--v4-ok);
}
.avatarStatus[data-status="warn"] {
  background: var(--v4-warn);
}
.fieldLabels {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-field-label);
  min-width: 0;
}
.fieldLabelRow {
  display: flex;
  align-items: center;
  gap: var(--v4-space-4);
  min-width: 0;
}
.globHelp {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-4);
}
.fieldHelp {
  margin-block: calc((var(--v4-type-field-label-line-height) - var(--v4-size-control-xs)) / 2);
  color: var(--v4-muted);
}
.fieldDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  margin: 0;
  color: var(--v4-muted, var(--muted-foreground));
}
.fieldError {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-6);
  margin: 0;
  color: var(--v4-bad);
}
.fieldError > svg {
  flex: none;
  margin-block-start: calc((var(--v4-type-small-line-height) - 14px) / 2);
}
.fieldErrorLines {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-2);
}
.fieldControl {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-field-label);
  flex: 1;
  min-width: 0;
}
.badge {
  --v4-badge-glyph: var(--v4-size-badge-glyph);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
  height: var(--v4-size-badge);
  padding: 0 var(--v4-space-8);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
  border-radius: 0;
}
.badge.mono {
  font-family: var(--v4-type-mono-sm-font-family);
}
.badge[data-slot][data-tone] {
  border-color: var(--v4-line-soft);
  color: var(--v4-muted);
  background: transparent;
}
.badge[data-size="sm"] {
  --v4-badge-glyph: var(--v4-size-badge-glyph-sm);
  height: var(--v4-size-badge-sm);
  padding-inline: var(--v4-space-6);
  line-height: calc(var(--v4-size-badge-sm) - 2 * var(--v4-size-control-border));
}
.badge:is([data-size="control-sm"], [data-size="control-md"], [data-size="control-lg"]) {
  --v4-badge-glyph: var(--v4-size-icon);
  gap: var(--v4-space-control-gap);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.badge[data-size="control-sm"] {
  --v4-badge-glyph: var(--v4-size-icon-sm);
  height: var(--v4-size-control-sm);
  padding-inline: var(--v4-space-control-inline-sm);
}
.badge[data-size="control-md"] {
  height: var(--v4-size-control-md);
  padding-inline: var(--v4-space-control-inline-md);
}
.badge[data-size="control-lg"] {
  height: var(--v4-size-control-lg);
  padding-inline: var(--v4-space-control-inline);
}
.badge[data-slot][data-tone="soft"] {
  border-color: var(--v4-line-soft);
  background: var(--v4-line-soft);
  color: var(--v4-text2);
}
.badge[data-slot][data-tone="solid"] {
  border-color: var(--v4-ink);
  background: var(--v4-ink);
  color: var(--v4-on-ink);
}
.badge[data-slot][data-tone="accent"] {
  border-color: var(--v4-accent);
  background: var(--v4-accent);
  color: var(--v4-on-accent);
}
.badge[data-slot][data-tone="ok"] {
  border-color: var(--v4-ok-line);
  background: var(--v4-ok-bg);
  color: var(--v4-ok);
}
.badge[data-slot][data-tone="warn"] {
  border-color: var(--v4-warn-line);
  background: var(--v4-warn-bg);
  color: var(--v4-warn);
}
.badge[data-slot][data-tone="bad"] {
  border-color: var(--v4-bad-line);
  background: var(--v4-bad-bg);
  color: var(--v4-bad);
}
.badge[data-slot][data-tone="info"] {
  border-color: var(--v4-info-line);
  background: var(--v4-info-bg);
  color: var(--v4-info);
}
.badgeDot {
  width: 6px;
  height: 6px;
  background: currentColor;
  flex-shrink: 0;
}
.steps .step {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}
.steps .step::before {
  content: "";
  display: block;
  width: 100%;
  height: 6px;
  background: var(--v4-line-soft);
}
.steps .step[data-complete]::before {
  background: var(--v4-ink);
}
.steps .step[data-current]::before {
  background: repeating-linear-gradient(135deg, var(--v4-ink) 0 2px, var(--v4-line-soft) 2px 4px);
}
.fieldset {
  min-width: 0;
  width: 100%;
  padding: 0;
  border: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.fieldset > legend {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-field-label-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
  margin-bottom: 6px;
}
.alert[data-tone="neutral"] {
  background: var(--v4-paper);
  border-color: var(--v4-line-soft);
  color: var(--v4-ink);
}
.alert[data-tone="neutral"] > svg {
  color: var(--v4-muted);
}
.alert[data-tone="info"] {
  background: var(--v4-info-bg);
  border-color: var(--v4-info-line);
  color: var(--v4-info);
}
.alert[data-tone="ok"] {
  background: var(--v4-ok-bg);
  border-color: var(--v4-ok-line);
  color: var(--v4-ok);
}
.alert[data-tone="warn"] {
  background: var(--v4-warn-bg);
  border-color: var(--v4-warn-line);
  color: var(--v4-warn);
}
.alert[data-tone="bad"] {
  background: var(--v4-bad-bg);
  border-color: var(--v4-bad-line);
  color: var(--v4-bad);
}
.alertActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--v4-space-8);
  padding-top: var(--v4-space-actions-gap);
}
.toastStack {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-8);
  width: max-content;
  max-width: min(var(--v4-size-toast), 100%);
}
.toastStack.toastFixed {
  max-width: min(var(--v4-size-toast), calc(100vw - 2 * var(--v4-space-16)));
}
.toast {
  border-radius: 0;
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-8);
  border: 1px solid var(--v4-line-soft, var(--border));
  background: var(--v4-toast-bg, var(--popover));
  color: var(--v4-ink, var(--foreground));
  box-shadow: var(--v4-shadow-pop, 0 4px 16px rgb(0 0 0 / 0.12));
  padding: var(--v4-space-12);
  --v4-toast-line: var(--v4-type-row-title-line-height);
}
.toast > svg {
  flex: none;
  height: var(--v4-toast-line);
}
.toastBody {
  min-width: 0;
  flex: 1 1 auto;
}
.toastTitle,
.toastDescription {
  overflow-wrap: anywhere;
}
.toast > button {
  flex: none;
  margin-block: calc((var(--v4-toast-line) - var(--v4-action-height)) / 2);
}
.toastActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--v4-space-4);
  margin-top: var(--v4-space-8);
  margin-inline-start: calc(-1 * var(--v4-space-control-inline-sm));
  contain: inline-size;
}
.toastActions > button {
  white-space: normal;
  max-width: 100%;
}
.avatarShape {
  border-radius: 0;
}
.avatarShape::after {
  content: "";
  position: absolute;
  inset: 0;
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
  mix-blend-mode: var(--v4-avatar-blend);
  pointer-events: none;
}
.avatarShape::after,
.avatarShape > [data-slot="avatar-fallback"],
.avatarShape > [data-slot="avatar-image"] {
  border-radius: inherit;
}
.avatarShape > [data-slot="avatar-fallback"] {
  font-size: inherit;
}
.avatarRing {
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-surface);
}
.avatarGroup {
  display: flex;
}
.avatarGroup > [data-slot="avatar"] + [data-slot="avatar"],
.avatarGroup > * + [data-slot="avatar-group-count"] {
  margin-inline-start: calc(-1 * var(--v4-space-4));
}
.avatarCount {
  border-radius: 0;
  background: var(--v4-tint);
  color: var(--v4-muted);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-surface);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  font-weight: var(--v4-type-caption-font-weight);
}
.avatarStatus {
  position: absolute;
  z-index: 1;
  inset-inline-end: calc(-1 * var(--v4-space-2));
  bottom: calc(-1 * var(--v4-space-2));
  width: var(--v4-space-8);
  height: var(--v4-space-8);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-surface);
  background: var(--v4-faint);
  border-radius: 0;
}

.fieldLegend {
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
  margin-bottom: var(--v4-space-field-label);
}
.fieldLegend[data-variant="label"] {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-field-label-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
}
.alertTitle {
  grid-column: 1;
  grid-row: 1;
  min-width: 0;
  font-family: var(--v4-type-row-title-font-family);
  font-size: var(--v4-type-row-title-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-row-title-font-weight);
  letter-spacing: var(--v4-type-row-title-letter-spacing);
}
.alertDescription {
  grid-column: 1;
  min-width: 0;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}

:is(.fieldDescription, .alertDescription) a:not([data-slot]) {
  color: var(--v4-link);
  text-decoration-line: none;
  text-decoration-thickness: var(--v4-size-control-border);
  text-underline-offset: var(--v4-space-3);
}
:is(.fieldDescription, .alertDescription) a:not([data-slot]):focus-visible {
  text-decoration-line: underline;
}
@media (hover: hover) {
  :is(.fieldDescription, .alertDescription) a:not([data-slot]):hover {
    color: var(--v4-text2);
    text-decoration-line: underline;
    text-decoration-thickness: var(--v4-space-2);
  }
}

.alert {
  position: relative;
  display: grid;
  width: 100%;
  grid-template-columns: minmax(0, 1fr);
  border: 1px solid var(--v4-line-soft);
  border-radius: 0;
  padding: var(--v4-space-12);
  gap: var(--v4-space-4) var(--v4-space-8);
  overflow-wrap: anywhere;
  text-align: start;
}
.alert[data-has-icon] {
  grid-template-columns: auto minmax(0, 1fr);
}
.alert > svg {
  grid-column: 1;
  grid-row: 1 / span 2;
  align-self: start;
  transform: translateY(var(--v4-space-2));
  color: currentColor;
}
.alert[data-has-icon] > :is(.alertTitle, .alertDescription) {
  grid-column: 2;
}
.alert[data-has-title] > .alertDescription {
  grid-row: 2;
}
.alert[data-has-action] {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-inline-end: var(--v4-space-12);
}
.alert[data-has-icon][data-has-action] {
  grid-template-columns: auto minmax(0, 1fr) auto;
}
.alertAction {
  position: static;
  grid-column: -2 / -1;
  grid-row: 1 / span 2;
  align-self: start;
}

.fieldTitle {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-field-label-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
}
.fieldGroup {
  gap: var(--v4-space-field-group);
}
.field {
  gap: var(--v4-space-field-label);
}
.field:not([data-orientation="horizontal"]) {
  max-width: var(--v4-size-measure-field);
}
.field[data-width="wide"]:not([data-orientation="horizontal"]) {
  max-width: var(--v4-size-measure-field-wide);
}
.field[data-orientation="horizontal"] {
  gap: var(--v4-space-12);
}
